// 13 months + prior calendar year window (relative to now).
const cfg = $('Config').first().json;
const months = Number(cfg.lookbackMonths) || 13;
const now = new Date();
const pad = n => (n < 10 ? '0' + n : '' + n);
const fmt = dt => dt.getUTCFullYear() + '-' + pad(dt.getUTCMonth() + 1) + '-' + pad(dt.getUTCDate());
const back = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - months, now.getUTCDate()));
const defaultFrom = fmt(back);
const py = now.getUTCFullYear() - 1;
const priorStart = py + '-01-01';
const priorEnd = py + '-12-31';
const loadStart = (defaultFrom < priorStart) ? defaultFrom : priorStart;
const endDay = fmt(now);
return [{ json: { startDay: loadStart, endDay: endDay, defaultFrom: defaultFrom, priorStart: priorStart, priorEnd: priorEnd, generatedAt: now.toISOString() } }];

// Build an opaque-id -> name map, live (names never persisted).
const body = $input.first() ? $input.first().json : {};
const map = {};
const edges = body && body.data && body.data.staff && body.data.staff.edges;
if(Array.isArray(edges)){ edges.forEach(function(e){ const c = e && e.node && e.node.contact; if(c && c.id){ map[c.id] = ((c.firstName||'') + ' ' + (c.lastName||'')).trim() || c.id; } }); }
return [{ json: { map: map, count: Object.keys(map).length } }];

// Parse the cached compact payload back into name-free records.
const row = $input.first() ? $input.first().json : {};
let obj = { ins:[], crs:[], recs:[], generatedAt:'' };
try { if(row && row.payload) obj = JSON.parse(row.payload); } catch(e){}
const g = obj.generatedAt || '';
const records = (obj.recs||[]).map(function(r){ return { ii: obj.ins[r[0]], ev: obj.crs[r[1]], s: r[2], e: r[3], et: r[4], h: r[5], g: g }; });
if(!records.length) return [{ json:{ __empty:true, g: g } }];
return records.map(function(json){ return { json: json }; });

// Instructor dashboard. Records are name-free (opaque id). Names + active-instructor allow-list come from the live map (excludes Left Company = Yes).
const win = $('Build Window').first().json;
const nameMap = ($('Resolve Names').first().json.map) || {};
const rows = $input.all().map(i => i.json).filter(r => !r.__empty);
const loadStart = String(win.startDay || '').slice(0,10);
const endDay = String(win.endDay || '').slice(0,10);
const defaultFrom = String(win.defaultFrom || loadStart).slice(0,10);
const priorStart = String(win.priorStart || '').slice(0,10);
const priorEnd = String(win.priorEnd || '').slice(0,10);
const cacheTime = (rows[0] && rows[0].g) ? String(rows[0].g).slice(0,19).replace('T',' ') : 'n/a';
const sub = 'Loaded ' + loadStart + ' to ' + endDay + ' (active instructors only) | data as of ' + cacheTime;
const B = JSON.stringify(rows.map(function(r){ return { ii:r.ii, ev:r.ev, s:r.s, e:r.e, et:r.et, h:r.h }; }));
const NM = JSON.stringify(nameMap);
const html = `<!DOCTYPE html>
<html lang='en'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width, initial-scale=1'>
<title>Instructor Utilization</title>
<script src='https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js'></script>
<style>
:root{--p:#6A3CE3;--pd:#4A25A8;--ink:#1c1233;--muted:#6b6580;--bg:#f5f3fb;--card:#fff;--line:#e7e2f5}
*{box-sizing:border-box}
body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--ink)}
header{background:linear-gradient(120deg,var(--p),var(--pd));color:#fff;padding:20px 24px}
header h1{margin:0;font-size:19px}
header p{margin:4px 0 0;font-size:13px;opacity:.85}
.wrap{max-width:1180px;margin:0 auto;padding:20px 24px 56px}
.bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}
.seg{display:inline-flex;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.seg button{border:0;background:#fff;font:inherit;padding:8px 14px;cursor:pointer;color:var(--ink)}
.seg button.on{background:var(--p);color:#fff}
label{font-size:13px;color:var(--muted)}
select,input[type=date]{font:inherit;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);max-width:280px}
.btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:8px;padding:8px 12px;font:inherit;cursor:pointer}
.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:6px 0 20px}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
.card .k{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.card .v{font-size:26px;font-weight:700;margin-top:6px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.panel{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
.panel h2{margin:0 0 12px;font-size:14px}
.chartbox{position:relative;height:300px}
table{width:100%;border-collapse:collapse;font-size:13px}
th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--line)}
th{color:var(--muted);cursor:pointer}
td.num,th.num{text-align:right}
#note{margin:8px 0;color:#8a6400;font-size:13px}
@media(max-width:820px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}
</style></head>
<body>
<header><h1>Instructor Utilization</h1><p>${sub}</p></header>
<div class='wrap'>
<div class='bar'><label>From</label><input type='date' id='ds' min='${loadStart}' max='${endDay}' value='${defaultFrom}'><label>To</label><input type='date' id='de' min='${loadStart}' max='${endDay}' value='${endDay}'><button id='p13' class='btn'>Last 13 months</button><button id='ppy' class='btn'>Prior year</button><button id='reset' class='btn'>Full range</button><label>Course</label><select id='cf'></select><span style='flex:1'></span><span class='seg' id='seg'><button data-m='d' class='on'>Days</button><button data-m='h'>Hours</button></span></div>
<div id='note'></div>
<div class='cards' id='cards'></div>
<div class='grid'>
<div class='panel'><h2 id='rt'>Top instructors</h2><div class='chartbox'><canvas id='rank'></canvas></div></div>
<div class='panel'><h2 id='tt'>Top courses</h2><div class='chartbox'><canvas id='type'></canvas></div></div>
</div>
<div class='panel' style='margin-top:16px'><h2 id='lt'>Courses - most taught</h2>
<table id='loc'><thead><tr><th class='num'>#</th><th>Course</th><th class='num'>Days</th><th class='num'>Hours</th><th class='num'>Sessions</th><th class='num'>Instructors</th></tr></thead><tbody></tbody></table></div>
<div class='panel' style='margin-top:16px'><h2>All instructors</h2>
<table id='tbl'><thead><tr><th data-s='n'>Instructor</th><th class='num' data-s='d'>Days taught</th><th class='num' data-s='h'>Hours taught</th><th class='num' data-s='b'>Sessions</th><th class='num' data-s='c'>Courses</th></tr></thead><tbody></tbody></table>
</div></div>
<script>
var B = ${B};
var NAMEMAP = ${NM};
var LOAD_S='${loadStart}', LOAD_E='${endDay}', DEF_F='${defaultFrom}', PY_S='${priorStart}', PY_E='${priorEnd}';
var from=DEF_F, to=LOAD_E, metric='d', cf='', sk='d', sd=-1, rankC, courseC, ROWS=[];
function one(n){return (Math.round(n*10)/10).toLocaleString();}
function nm(id){return NAMEMAP[id]||id;}
function active(id){return Object.prototype.hasOwnProperty.call(NAMEMAP,id);}
function inRange(b){return b.s>=from && b.s<=to;}
function daysOf(b){var s=b.s,e=b.e;if(b.et==='00:00:00'&&e>s){var d=new Date(e+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-1);e=d.toISOString().slice(0,10);}var out=[];var cur=new Date(s+'T00:00:00Z');var last=new Date(e+'T00:00:00Z');while(cur<=last){out.push(cur.toISOString().slice(0,10));cur.setUTCDate(cur.getUTCDate()+1);}return out;}
function base(){return B.filter(function(r){return inRange(r) && active(r.ii);});}
function courses(){var s=[];base().forEach(function(r){if(s.indexOf(r.ev)<0)s.push(r.ev);});return s.sort();}
function compute(){var m={};base().forEach(function(r){if(cf && r.ev!==cf)return;var x=m[r.ii];if(!x){x=m[r.ii]={ii:r.ii,days:{},h:0,b:0,cs:{}};}x.b+=1;x.h+=r.h;x.cs[r.ev]=1;daysOf(r).forEach(function(d){x.days[d]=1;});});ROWS=Object.keys(m).map(function(k){var x=m[k];return {n:nm(x.ii),d:Object.keys(x.days).length,h:Math.round(x.h*100)/100,b:x.b,c:Object.keys(x.cs).length};});}
function courseAgg(){var m={};base().forEach(function(r){var x=m[r.ev];if(!x){x=m[r.ev]={ev:r.ev,days:{},h:0,b:0,ins:{}};}x.b+=1;x.h+=r.h;x.ins[r.ii]=1;daysOf(r).forEach(function(d){x.days[d]=1;});});var a=Object.keys(m).map(function(k){var x=m[k];return {ev:x.ev,d:Object.keys(x.days).length,h:Math.round(x.h*100)/100,b:x.b,ins:Object.keys(x.ins).length};});a.sort(function(p,q){return q[metric]-p[metric];});return a;}
function fillCourses(){var sel=document.getElementById('cf');var keep=cf;sel.innerHTML='<option>All courses</option>'+courses().map(function(t){return '<option>'+t+'</option>';}).join('');if(courses().indexOf(keep)>=0){cf=keep;sel.value=keep;}else{cf='';}}
function cards(){var td=ROWS.reduce(function(a,r){return a+r.d;},0);var th=ROWS.reduce(function(a,r){return a+r.h;},0);var c=[['Instructors',ROWS.length],['Courses',courses().length],['Total days taught',td.toLocaleString()],['Total hours taught',one(th)]];document.getElementById('cards').innerHTML=c.map(function(x){return '<div class=card><div class=k>'+x[0]+'</div><div class=v>'+x[1]+'</div></div>';}).join('');}
function rank(){var key=metric;var v=ROWS.slice().sort(function(a,b){return b[key]-a[key];}).slice(0,15);document.getElementById('rt').textContent='Top instructors by '+(metric==='d'?'days':'hours')+' taught';if(rankC)rankC.destroy();rankC=new Chart(document.getElementById('rank'),{type:'bar',data:{labels:v.map(function(r){return r.n;}),datasets:[{data:v.map(function(r){return r[key];}),backgroundColor:'#6A3CE3',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',plugins:{legend:{display:false}},scales:{y:{ticks:{font:{size:11}}}}}});}
function courseChart(){var key=metric;var a=courseAgg().slice(0,12);document.getElementById('tt').textContent='Top courses by '+(metric==='d'?'days':'hours');if(courseC)courseC.destroy();courseC=new Chart(document.getElementById('type'),{type:'bar',data:{labels:a.map(function(r){return r.ev;}),datasets:[{data:a.map(function(r){return r[key];}),backgroundColor:'#3CB9C4',borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,indexAxis:'y',plugins:{legend:{display:false}},scales:{y:{ticks:{font:{size:10}}}}}});}
function courseTable(){document.getElementById('lt').textContent='Courses - most taught (by '+(metric==='d'?'days':'hours')+')';document.querySelector('#loc tbody').innerHTML=courseAgg().map(function(r,i){return '<tr><td class=num>'+(i+1)+'</td><td>'+r.ev+'</td><td class=num>'+r.d.toLocaleString()+'</td><td class=num>'+one(r.h)+'</td><td class=num>'+r.b.toLocaleString()+'</td><td class=num>'+r.ins+'</td></tr>';}).join('');}
function tbl(){var v=ROWS.slice().sort(function(a,b){var x=a[sk],y=b[sk];if(typeof x==='string')return x.localeCompare(y)*sd;return (x-y)*sd;});document.querySelector('#tbl tbody').innerHTML=v.map(function(r){return '<tr><td>'+r.n+'</td><td class=num>'+r.d.toLocaleString()+'</td><td class=num>'+one(r.h)+'</td><td class=num>'+r.b.toLocaleString()+'</td><td class=num>'+r.c.toLocaleString()+'</td></tr>';}).join('');}
function render(){cards();rank();courseChart();courseTable();tbl();document.getElementById('note').textContent=ROWS.length?'':'No teaching sessions in the selected date range.';}
function recompute(){compute();fillCourses();render();}
function setRange(a,b){from=a;to=b;document.getElementById('ds').value=a;document.getElementById('de').value=b;recompute();}
document.getElementById('ds').addEventListener('change',function(e){from=e.target.value||LOAD_S;recompute();});
document.getElementById('de').addEventListener('change',function(e){to=e.target.value||LOAD_E;recompute();});
document.getElementById('p13').addEventListener('click',function(){setRange(DEF_F,LOAD_E);});
document.getElementById('ppy').addEventListener('click',function(){setRange(PY_S,PY_E);});
document.getElementById('reset').addEventListener('click',function(){setRange(LOAD_S,LOAD_E);});
document.getElementById('cf').addEventListener('change',function(e){cf=(e.target.selectedIndex===0)?'':e.target.value;compute();render();});
Array.prototype.forEach.call(document.querySelectorAll('#seg button'),function(b){b.addEventListener('click',function(){Array.prototype.forEach.call(document.querySelectorAll('#seg button'),function(x){x.classList.remove('on');});b.classList.add('on');metric=b.getAttribute('data-m');rank();courseChart();courseTable();});});
Array.prototype.forEach.call(document.querySelectorAll('#tbl th'),function(th){th.addEventListener('click',function(){var k=th.getAttribute('data-s');if(!k)return;sd=(sk===k)?-sd:-1;sk=k;tbl();});});
recompute();
</script></body></html>`;
const fileName = 'Instructor Utilization Dashboard ' + loadStart + ' to ' + endDay + '.html';
return [{ json: { fileName: fileName }, binary: { data: { data: Buffer.from(html, 'utf8').toString('base64'), fileName: fileName, mimeType: 'text/html', fileExtension: 'html' } } }];
